mapper.select:
select u.id, u.created_at, u.user_code, u.user_id, u.user_name, u.center_code, u.role_key
from ERP_USER u
         JOIN erp_user_role_code r ON u.role_key = r.role_key
where center_code = #{centerCode}
  AND r.role_num <= #{roleNum}
  AND (#{type} = 'all' OR u.type = #{type})

mapper.update:
update erp_user
set password_hash = #{hashedPassword}
where user_code = #{userCode}
